index=subprocess.check_output(['git','-C',str(B),'ls-files','--stage','knowledge'],text=True).strip();out={'status':'passed','checks':checks,'canonical_counts':{'entries':2534,'names':4281,'observations':25940,'new_public_endpoints':6,'new_proof_supports':12,'new_source_certificates':4,'new_observation_groups':840},'knowledge_main_head':head,'knowledge_origin_main':origin,'knowledge_commit_scoped_paths':949,'distribution_index_at_review':index,'pending_parent_integration':'Parent stages, commits and pushes distribution gitlink to exact reviewed knowledge HEAD after this receipt; distribution integration statement is conditional on that planned completion.','wording_note':'Reviewed final wording correction:112 recipe strata and Recipe table label; four orientation-composition recipes belong to one mathematical family.','limits':'Document/canonical review only; no timing, canonical edits or git mutations. Five prior regressions, full uncertainty, point losses and strong-control limits retained.','bindings':{str(p.relative_to(B)):sha(p)for p in [R/'REPORT.md',R/'write-report.py',R/'report.html',R/'report.jpg',R/'verification.json',R/'publication.json',R/'observations.json',R/'review/final-performance-review.json',B/'README.md',B/'knowledge/README.md',Path(__file__)]}};(R/'review/final-delivery-review.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'status':'passed','knowledge_head':head,'pending_gitlink':index,'checks':checks}))
